    stdout.push(chunk);
  });
    // ...
  p.stderr.on('data', function (chunk) {
    stderr.push(chunk);
  });
    // ...
  p.on('close', function (code) {

    if (code !== 0) {
      var str = Buffer.concat(stderr).toString();
      var err = new Error(str.replace(/^ERROR: /, ''));

      return cb(err);
    }

    cb(null, Buffer.concat(stdout).toString());
  });
    // ...
}

